                    <div key={line} className={index === 0 ? 'text-[#5de6ff]' : ''}>
                      {line}
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        {step === 'granted' && (
          <div className="relative w-full max-w-[720px]">
