                </div>

                <div className="mx-auto mt-8 flex h-32 w-32 items-center justify-center rounded-3xl border border-white/10 bg-[#020408]/40 shadow-[0_0_40px_rgba(37,99,235,0.15)]">
                  <ShieldCheck className="h-14 w-14 text-[#b4c5ff]" />
